options.css:
/* Shared base for every retro HTML Graphics panel. Each panel renders in its own shadow DOM, so apply_theme.py
   copies this into each panel's CSS. Tokens match tokens/tokens.json and web/retro.css. */
* { box-sizing: border-box; }
.rt-panel {
  --rt-black: #050409;
  --rt-text: #f6f3ff;
  --rt-muted: #aba4cd;
  --rt-line: rgba(166, 61, 255, 0.3);
  --rt-c1: #4d5bff; --rt-c2: #a63dff; --rt-c3: #ff2e9a; --rt-c4: #ff3b3b;
  --rt-c5: #ff8c1a; --rt-c6: #ffd60a; --rt-c7: #9dff2e;
  --rt-cyan: #2de2ff; --rt-yellow: #ffef5c; --rt-red: #ff4d5e; --rt-green: #5dff8f; --rt-orange: #ff8c1a;
  --rt-stripes: linear-gradient(90deg, var(--rt-c1) 0 14.29%, var(--rt-c2) 0 28.57%, var(--rt-c3) 0 42.86%,
    var(--rt-c4) 0 57.14%, var(--rt-c5) 0 71.43%, var(--rt-c6) 0 85.71%, var(--rt-c7) 0);
  --rt-trail: linear-gradient(180deg, var(--rt-c2) 0 3px, transparent 3px 5px, var(--rt-c3) 5px 8px,
    transparent 8px 10px, var(--rt-c6) 10px 13px);
  --rt-glow-yellow: 0 0 2px rgba(255, 250, 210, 0.9), 0 0 10px rgba(255, 225, 60, 0.75), 0 0 26px rgba(255, 170, 20, 0.4);
  --rt-glow-cyan: 0 0 2px rgba(220, 250, 255, 0.9), 0 0 8px rgba(45, 226, 255, 0.65), 0 0 20px rgba(45, 140, 255, 0.4);
  --rt-glow-green: 0 0 2px rgba(220, 255, 230, 0.9), 0 0 8px rgba(93, 255, 143, 0.6), 0 0 18px rgba(40, 200, 90, 0.35);
  --rt-glow-red: 0 0 2px rgba(255, 220, 220, 0.9), 0 0 9px rgba(255, 77, 94, 0.75), 0 0 22px rgba(255, 40, 40, 0.4);
  --rt-split: -1.5px 0 rgba(255, 46, 154, 0.65), 1.5px 0 rgba(45, 226, 255, 0.65);
  --rt-font-display: "Exo 2", "Segoe UI", sans-serif;
  --rt-font-body: "Space Grotesk", "Segoe UI", system-ui, sans-serif;
  --rt-font-pixel: "Press Start 2P", ui-monospace, monospace;
  --rt-font-term: "VT323", ui-monospace, monospace;
  width: 100%;
  height: 100%;
  color: var(--rt-text);
  font-family: var(--rt-font-body);
  container-type: inline-size;
}

/* Dark panel with the 7-colour stripe cap, the card look of the kit. */
.rt-box {
  position: relative;
  border: 1px solid var(--rt-line);
  border-radius: 10px;
  background:
    repeating-linear-gradient(180deg, rgba(0, 0, 0, 0.16) 0 1px, transparent 1px 3px),
    linear-gradient(180deg, rgba(22, 17, 42, 0.92), rgba(10, 8, 20, 0.96));
  box-shadow: 0 18px 44px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.04);
}
.rt-box::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  border-radius: 9px 9px 0 0;
  background: var(--rt-stripes);
  opacity: 0.9;
}

.rt-label {
  color: var(--rt-cyan);
  font: 400 9px/1.4 var(--rt-font-pixel);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  text-shadow: 0 0 8px rgba(45, 226, 255, 0.5);
}

/* Speed stripes + drawn neon ring, the ident mark. */
.rt-mark { --rt-mark-size: 80px; display: flex; align-items: center; gap: calc(var(--rt-mark-size) * 0.14); flex: none; }
.rt-mark__stripes { display: flex; align-items: center; gap: calc(var(--rt-mark-size) * 0.05);
  height: calc(var(--rt-mark-size) * 0.9); transform: skewX(-22deg); }
.rt-mark__stripes i { --c: var(--rt-c1); display: block; width: calc(var(--rt-mark-size) * 0.085); height: 100%;
  border-radius: 999px; background: var(--c); box-shadow: 0 0 7px var(--c);
  animation: rt-trail-in 700ms cubic-bezier(0.16, 1, 0.3, 1) both; animation-delay: calc(var(--i, 0) * 45ms); }
.rt-mark__stripes i:nth-child(2) { --c: var(--rt-c2); --i: 1; }
.rt-mark__stripes i:nth-child(3) { --c: var(--rt-c3); --i: 2; }
.rt-mark__stripes i:nth-child(4) { --c: var(--rt-c4); --i: 3; }
.rt-mark__stripes i:nth-child(5) { --c: var(--rt-c5); --i: 4; }
.rt-mark__stripes i:nth-child(6) { --c: var(--rt-c6); --i: 5; }
.rt-mark__stripes i:nth-child(7) { --c: var(--rt-c7); --i: 6; }
.rt-mark__ring { position: relative; display: grid; place-items: center; width: var(--rt-mark-size);
  height: var(--rt-mark-size); flex: none; }
.rt-mark__ring svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; transform: rotate(-90deg); }
.rt-mark__ring circle { fill: none; stroke: var(--rt-yellow); stroke-width: 6; stroke-linecap: round;
  stroke-dasharray: 289; stroke-dashoffset: 289;
  filter: drop-shadow(0 0 3px #fff6a0) drop-shadow(0 0 9px rgba(255, 214, 10, 0.85));
  animation: rt-ring-draw 700ms cubic-bezier(0.65, 0, 0.35, 1) 300ms forwards; }
.rt-mark__ring img { width: 90%; height: 90%; object-fit: contain; opacity: 0; transform: scale(0.6);
  animation: rt-pop 450ms cubic-bezier(0.34, 1.56, 0.64, 1) 650ms forwards; }
/* No logo configured: the title's first letter in the ring, in pixel type. */
.rt-mark__glyph { color: var(--rt-cyan); font: 400 calc(var(--rt-mark-size) * 0.36)/1 var(--rt-font-pixel);
  text-shadow: var(--rt-glow-cyan); opacity: 0; animation: rt-pop 450ms cubic-bezier(0.34, 1.56, 0.64, 1) 650ms forwards; }

/* RGB-split glitch copies (screen readers read the heading once: empty alt text on the copies). */
.rt-glitch { position: relative; }
.rt-glitch::before, .rt-glitch::after {
  content: attr(data-text);
  content: attr(data-text) / "";
  position: absolute; inset: 0; pointer-events: none; opacity: 0;
  background: none; -webkit-text-stroke: 0; text-shadow: none; filter: none;
}
.rt-glitch::before { color: var(--rt-c3); -webkit-text-fill-color: var(--rt-c3); animation: rt-glitch-a 7s steps(1, end) infinite; }
.rt-glitch::after { color: var(--rt-cyan); -webkit-text-fill-color: var(--rt-cyan); animation: rt-glitch-b 7s steps(1, end) infinite; }
.rt-panel[data-fx="off"] .rt-glitch::before, .rt-panel[data-fx="off"] .rt-glitch::after { animation: none; }

@keyframes rt-blink { 50% { opacity: 0; } }
@keyframes rt-flicker-on { 0% { opacity: 0; } 8% { opacity: 1; } 12% { opacity: 0.15; } 20% { opacity: 1; }
  26% { opacity: 0.4; } 34%, 100% { opacity: 1; } }
@keyframes rt-trail-in { 0% { opacity: 0; transform: translateX(-40vw) scaleX(5); filter: blur(6px); }
  55% { opacity: 1; } 100% { opacity: 1; transform: none; filter: none; } }
@keyframes rt-trail-draw { from { transform: scaleX(0); } }
@keyframes rt-ring-draw { to { stroke-dashoffset: 0; } }
@keyframes rt-pop { to { opacity: 1; transform: none; } }
@keyframes rt-glitch-a {
  0%, 90.9% { opacity: 0; transform: none; clip-path: inset(0 0 0 0); }
  91% { opacity: 0.85; transform: translate(-4px, 0); clip-path: inset(12% 0 60% 0); }
  92.5% { opacity: 0.85; transform: translate(5px, 0); clip-path: inset(58% 0 18% 0); }
  94% { opacity: 0.85; transform: translate(-3px, 0); clip-path: inset(32% 0 44% 0); }
  95.5%, 100% { opacity: 0; transform: none; clip-path: inset(0 0 0 0); } }
@keyframes rt-glitch-b {
  0%, 91.4% { opacity: 0; transform: none; clip-path: inset(0 0 0 0); }
  91.5% { opacity: 0.85; transform: translate(4px, 0); clip-path: inset(64% 0 10% 0); }
  93% { opacity: 0.85; transform: translate(-5px, 0); clip-path: inset(8% 0 70% 0); }
  94.5% { opacity: 0.85; transform: translate(3px, 0); clip-path: inset(40% 0 38% 0); }
  96%, 100% { opacity: 0; transform: none; clip-path: inset(0 0 0 0); } }
@keyframes rt-alarm { 0%, 100% { box-shadow: 0 0 0 1px var(--rt-red), 0 0 22px rgba(255, 77, 94, 0.55); }
  50% { box-shadow: 0 0 0 1px rgba(255, 77, 94, 0.4), 0 0 6px rgba(255, 77, 94, 0.2); } }

@media (prefers-reduced-motion: reduce) {
  .rt-panel *, .rt-panel *::before, .rt-panel *::after {
    animation-duration: 0.01ms !important; animation-delay: 0s !important; animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important; }
}

.hud { display: grid; grid-template-rows: auto 1fr; gap: 10px; padding: 2px; }

.hud__top {
  display: flex;
  align-items: center;
  gap: 22px;
  padding: 14px 18px 12px;
  overflow: hidden;
  background:
    repeating-linear-gradient(180deg, rgba(0, 0, 0, 0.16) 0 1px, transparent 1px 3px),
    radial-gradient(60% 140% at 18% 120%, rgba(255, 46, 154, 0.22), transparent 60%),
    radial-gradient(50% 120% at 90% -20%, rgba(77, 91, 255, 0.25), transparent 60%),
    linear-gradient(180deg, rgba(22, 17, 42, 0.95), rgba(8, 6, 16, 0.97));
}
/* A strip of synthwave floor along the bottom of the header. */
.hud__top::after {
  content: "";
  position: absolute;
  left: -20%;
  right: -20%;
  bottom: -40px;
  height: 90px;
  background-image:
    linear-gradient(180deg, rgba(255, 46, 154, 0.35) 1px, transparent 1px),
    linear-gradient(90deg, rgba(166, 61, 255, 0.3) 1px, transparent 1px);
  background-size: 48px 18px;
  transform: perspective(160px) rotateX(55deg);
  transform-origin: 50% 0;
  -webkit-mask-image: linear-gradient(180deg, transparent, #000 60%);
  mask-image: linear-gradient(180deg, transparent, #000 60%);
  pointer-events: none;
  opacity: 0.55;
}
.hud__mark { --rt-mark-size: 76px; position: relative; z-index: 1; }
.hud__titles { position: relative; z-index: 1; flex: 1; min-width: 0; display: grid; gap: 4px; }
.hud__title {
  font: italic 900 46px/0.95 var(--rt-font-display);
  letter-spacing: 0.01em;
  text-transform: uppercase;
  color: transparent;
  background: linear-gradient(180deg, #fff 0%, #fff 28%, #a8dcff 47%, #2b1766 50%, #ff6fd2 54%, #ffd9f2 76%, #fff 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-stroke: 1px rgba(255, 255, 255, 0.28);
  filter: drop-shadow(0 0 8px rgba(255, 46, 154, 0.5)) drop-shadow(0 0 22px rgba(77, 91, 255, 0.35));
  white-space: nowrap;
  animation: rt-flicker-on 900ms linear 0.2s both;
}
.hud__status {
  font: 400 23px/1.1 var(--rt-font-term);
  letter-spacing: 0.05em;
  color: var(--rt-green);
  text-shadow: var(--rt-glow-green);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.hud__status[data-level="warn"] { color: var(--rt-yellow); text-shadow: var(--rt-glow-yellow); }
.hud__status[data-level="crit"] { color: #ff8b96; text-shadow: var(--rt-glow-red); }
.hud__status[data-level="crit"] #hud-status-text { animation: rt-blink 1s steps(2, jump-none) infinite; }
.hud__cursor::after { content: "\2588"; content: "\2588" / ""; margin-left: 4px; animation: rt-blink 1s steps(2, jump-none) infinite; }

.hud__side { position: relative; z-index: 1; display: grid; justify-items: end; gap: 8px; }
.hud__chips { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 7px; max-width: 380px; }
.hud__chip {
  padding: 3px 9px 4px;
  border: 1px solid rgba(45, 226, 255, 0.45);
  border-radius: 4px;
  background: rgba(45, 226, 255, 0.06);
  color: var(--rt-cyan);
  font: 400 18px/1 var(--rt-font-term);
  letter-spacing: 0.06em;
  text-shadow: 0 0 6px rgba(45, 226, 255, 0.55);
  white-space: nowrap;
}
.hud__fx {
  padding: 6px 9px;
  border: 1px solid rgba(93, 255, 143, 0.45);
  border-radius: 4px;
  background: none;
  color: var(--rt-green);
  font: 400 8px/1 var(--rt-font-pixel);
  letter-spacing: 0.12em;
  text-shadow: var(--rt-glow-green);
  cursor: pointer;
}
.hud__fx[aria-pressed="false"] { color: var(--rt-muted); border-color: var(--rt-line); text-shadow: none; }
.hud__fx:hover, .hud__fx:focus-visible { border-color: var(--rt-cyan); outline: none; }

.hud__grid { display: grid; grid-template-columns: repeat(var(--rt-cols, 6), minmax(0, 1fr)); gap: 10px; min-height: 0; }
.meter { display: grid; align-content: space-between; gap: 6px; padding: 12px 14px 10px; min-width: 0; transition: box-shadow 250ms ease; }
.meter__value {
  color: var(--rt-yellow);
  font: italic 900 40px/1 var(--rt-font-display);
  letter-spacing: 0.01em;
  text-shadow: var(--rt-split), var(--rt-glow-yellow);
  white-space: nowrap;
}
.meter__hint { color: var(--rt-muted); font: 400 17px/1.1 var(--rt-font-term); letter-spacing: 0.04em; text-transform: uppercase;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
/* 20-segment arcade VU bar: green, then yellow, then red. */
.meter__bar { display: grid; grid-template-columns: repeat(20, minmax(0, 1fr)); gap: 3px; height: 13px; }
.meter__bar i { border-radius: 2px; background: rgba(255, 255, 255, 0.06); }
.meter__bar i.on { background: var(--rt-green); box-shadow: 0 0 6px rgba(93, 255, 143, 0.75); }
.meter__bar i.on:nth-child(n + 13) { background: var(--rt-c6); box-shadow: 0 0 6px rgba(255, 214, 10, 0.8); }
.meter__bar i.on:nth-child(n + 17) { background: var(--rt-red); box-shadow: 0 0 7px rgba(255, 77, 94, 0.85); }
.meter[data-state="warn"] .meter__value { color: var(--rt-orange); text-shadow: var(--rt-split), 0 0 10px rgba(255, 140, 26, 0.7); }
.meter[data-state="crit"] { animation: rt-alarm 1.2s ease-in-out infinite; }
.meter[data-state="crit"] .meter__value { color: #ff8b96; text-shadow: var(--rt-split), var(--rt-glow-red); }

/* Narrow panels (phones, half-width layouts): 3 then 2 meters per row, smaller type. */
@container (max-width: 1050px) {
  .hud__grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .meter { padding: 8px 10px; }
  .meter__value { font-size: 26px; }
  .hud__title { font-size: 36px; }
}
@container (max-width: 640px) {
  .hud__top { flex-wrap: wrap; gap: 12px; }
  .hud__mark { --rt-mark-size: 54px; }
  .hud__side { justify-items: start; }
  .hud__chips { justify-content: flex-start; }
  .hud__grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .hud__title { font-size: 30px; }
}

options.onRender:
// retro-neon-ui for Grafana: page runtime. apply_theme.py prepends this to the onRender code of ONE HTML Graphics
// panel (the theme carrier). It runs on every data refresh, so it is idempotent:
// - adds one <style id="rt-grafana-theme"> (replaced only when the build VERSION changes) and one CRT overlay;
// - sets body.rt-grafana ONLY while the URL is one of the themed dashboards (Grafana is a single-page app, so a
//   700 ms check switches the theme off as soon as you navigate elsewhere);
// - keeps body.rt-fx-off in sync with the CRT FX switch (localStorage "rt-fx");
// - plays the attract-mode intro at most every 12 h (never with reduced motion or FX off; ?rt-intro forces it).
// Placeholders (__RT_*__) are filled by apply_theme.py.
(() => {
  const VERSION = "rt-grafana-40ee62e8b8d4";
  const DASH_UIDS = ["retro-neon-demo"];
  const INTRO = {"title": "NEON OPS", "tag": "System overview"}; // null, or { title, tag, logo }
  const W = window;
  const state = W.__rtGrafana || (W.__rtGrafana = {});
  const esc = (s) => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  // Exact uid match, kept in shared state so the single timer always uses the dashboard that rendered last.
  // Not anchored to the start: a Grafana served under a sub-path has /grafana/d/<uid>/... paths.
  state.pathRe = new RegExp('/d/(' + DASH_UIDS.map(esc).join('|') + ')(/|$)');

  let style = document.getElementById('rt-grafana-theme');
  if (!style) {
    style = document.createElement('style');
    style.id = 'rt-grafana-theme';
    document.head.appendChild(style);
  }
  if (style.dataset.version !== VERSION) {
    style.textContent = "/* retro-neon-ui for Grafana: the page around the panels. Injected once by the theme carrier panel's runtime; every rule is scoped to body.rt-grafana, which is only set while a themed dashboard's URL is open, so other dashboards are untouched. Measured on Grafana 13.2.4; an upgrade can move these hooks (the data panels keep working). Grafana's own class names are generated (css-xxxx), so the selectors use its stable data-testid and data-viz-panel-key attributes. Fonts are embedded (no third-party font requests). */ @font-face { font-family: \"Exo 2\"; font-style: italic; font-weight: 400 900; font-display: swap; src: url(data:font/woff2;base64,) format(\"woff2\"); } @font-face { font-family: \"Space Grotesk\"; font-style: normal; font-weight: 400 700; font-display: swap; src: url(data:font/woff2;base64,) format(\"woff2\"); } @font-face { font-family: \"Press Start 2P\"; font-style: normal; font-weight: 400; font-display: swap; src: url(data:font/ttf;base64,) format(\"truetype\"); } @font-face { font-family: \"VT323\"; font-style: normal; font-weight: 400; font-display: swap; src: url(data:font/woff2;base64,) format(\"woff2\"); } @property --rt-draw { syntax: \"<angle>\"; inherits: false; initial-value: 360deg; } body.rt-grafana { --rt-black: #050409; --rt-text: #f6f3ff; --rt-muted: #aba4cd; --rt-line: rgba(166, 61, 255, 0.3); --rt-c1: #4d5bff; --rt-c2: #a63dff; --rt-c3: #ff2e9a; --rt-c4: #ff3b3b; --rt-c5: #ff8c1a; --rt-c6: #ffd60a; --rt-c7: #9dff2e; --rt-cyan: #2de2ff; --rt-yellow: #ffef5c; --rt-red: #ff4d5e; --rt-green: #5dff8f; --rt-stripes: linear-gradient(90deg, var(--rt-c1) 0 14.29%, var(--rt-c2) 0 28.57%, var(--rt-c3) 0 42.86%, var(--rt-c4) 0 57.14%, var(--rt-c5) 0 71.43%, var(--rt-c6) 0 85.71%, var(--rt-c7) 0); --rt-font-display: \"Exo 2\", \"Segoe UI\", sans-serif; --rt-font-body: \"Space Grotesk\", \"Segoe UI\", system-ui, sans-serif; --rt-font-pixel: \"Press Start 2P\", ui-monospace, monospace; --rt-font-term: \"VT323\", ui-monospace, monospace; } /* ---------- Page background ---------- */ body.rt-grafana main#pageContent, body.rt-grafana [data-testid=\"data-testid DashboardSidebarSplitter primary body\"], body.rt-grafana [data-testid=\"data-testid DashboardSidebarSplitter body container\"] { background: radial-gradient(70rem 36rem at 50% -10%, rgba(166, 61, 255, 0.16), transparent 70%), radial-gradient(50rem 30rem at 100% 105%, rgba(255, 46, 154, 0.08), transparent 70%), var(--rt-black) !important; } /* ---------- Top bar and dashboard controls ---------- */ /* The full-width top header is the <header> that holds the nav toolbar (Grafana 13.2.4). */ /* No position override here: Grafana positions this header itself (setting it broke the layout once). */ body.rt-grafana header:has([data-testid=\"data-testid Nav toolbar\"]) { background: rgba(5, 4, 9, 0.96) !important; border-bottom: 0 !important; } body.rt-grafana [class*=\"dashboard-controls-chrome\"] { background: transparent !important; } body.rt-grafana [data-testid=\"data-testid navigation mega-menu\"] { background: #07060d !important; border-right: 1px solid var(--rt-line) !important; } body.rt-grafana header:has([data-testid=\"data-testid Nav toolbar\"])::after { content: \"\"; position: absolute; left: 0; right: 0; bottom: 0; height: 2px; background: var(--rt-stripes); box-shadow: 0 0 10px rgba(255, 46, 154, 0.45); opacity: 0.85; } body.rt-grafana [data-testid$=\" breadcrumb\"] { font-family: var(--rt-font-term) !important; font-size: 18px !important; letter-spacing: 0.05em; text-transform: uppercase; } body.rt-grafana nav ol > li:last-child [data-testid$=\" breadcrumb\"] { color: var(--rt-yellow) !important; } body.rt-grafana [data-testid=\"data-testid dashboard controls\"] button, body.rt-grafana [data-testid=\"data-testid template variable\"] button, body.rt-grafana [data-testid=\"data-testid template variable\"] label, body.rt-grafana [data-testid=\"data-testid template variable\"] [class*=\"input-wrapper\"] { border-color: rgba(