    const d = Math.floor(s / 86400);
    const h = Math.floor((s % 86400) / 3600);
    const m = Math.floor((s % 3600) / 60);
    return d > 0 ? d + 'D ' + h + 'H' : h > 0 ? h + 'H ' + m + 'M' : m + 'M';
  },
};
const fmt = (v, kind) => (fin(v) ? (FORMATS[kind] || FORMATS.number)(v) : '--');
const tpl = (text, own) => String(text || '').replace(/\{([A-Za-z0-9_]+)(?::([a-z0-9]+))?\}/g, (_, ref, kind) =>
  fmt(ref === 'value' ? own : lastOf(ref), kind || 'number'));
const valueOf = (spec) => {
  if (typeof spec === 'string') return lastOf(spec);
  if (spec && Array.isArray(spec.ratio)) {
    const a = lastOf(spec.ratio[0]);
    const b = lastOf(spec.ratio[1]);
    return fin(a) && fin(b) && b !== 0 ? (a / b) * (spec.scale || 1) : null;
  }
  return null;
};
const setText = (id, text) => { const el = $(id); if (el) el.textContent = text; };
// Dashboard variables in the title ("$instance"): the plugin exposes Grafana's template service as getTemplateSrv.
const vars = (s) => {
  try { return typeof getTemplateSrv === 'function' ? getTemplateSrv().replace(String(s)) : String(s); } catch (e) { return String(s); }
};
const titleEl = htmlNode.querySelector('.hud__title');
if (titleEl && String(CFG.title || '').includes('$')) {
  const t = vars(CFG.title);
  if (titleEl.textContent !== t) { titleEl.textContent = t; titleEl.dataset.text = t; }
  const glyph = htmlNode.querySelector('.rt-mark__glyph');
  if (glyph) glyph.textContent = t.charAt(0).toUpperCase();
}

const crit = [];
const warn = [];
let anyData = false;
(CFG.meters || []).forEach((m, i) => {
  const v = valueOf(m.value);
  if (fin(v)) anyData = true;
  const level = !fin(v) ? '' : fin(m.crit) && v >= m.crit ? 'crit' : fin(m.warn) && v >= m.warn ? 'warn' : '';
  setText('v-' + i, fmt(v, m.format));
  if (m.hint) setText('h-' + i, tpl(m.hint, v));
  const max = m.bar && m.bar.maxRef ? lastOf(m.bar.maxRef) : (m.bar && m.bar.max) || 100;
  const fill = fin(v) && fin(max) && max > 0 ? (v / max) * 100 : null;
  const bar = $('b-' + i);
  if (bar) {
    if (bar.children.length !== 20) bar.innerHTML = '<i></i>'.repeat(20);
    const lit = fin(fill) ? Math.max(v > 0 ? 1 : 0, Math.min(20, Math.round(fill / 5))) : 0;
    [...bar.children].forEach((seg, j) => seg.classList.toggle('on', j < lit));
  }
  const card = $('m-' + i);
  if (card) { if (level) card.dataset.state = level; else delete card.dataset.state; }
  const name = m.status || String(m.label || '').toUpperCase();
  if (level === 'crit') crit.push(tpl(m.critText || name + ' CRITICAL', v));
  else if (level === 'warn') warn.push(tpl(m.warnText || name + ' HIGH', v));
});
(CFG.chips || []).forEach((chip, i) => setText('c-' + i, tpl(chip)));

const statusEl = $('hud-status');
if (statusEl) statusEl.dataset.level = !anyData ? 'warn' : crit.length ? 'crit' : warn.length ? 'warn' : 'ok';
setText('hud-status-text', !anyData ? '> ' + (CFG.noDataText || 'NO SIGNAL')
  : crit.length || warn.length ? '> ' + crit.concat(warn).join(' / ') : '> ' + (CFG.okText || 'ALL SYSTEMS NOMINAL'));

// CRT FX switch for any retro panel that renders a button#rt-fx (status-hud, banner). Shares state with the page
// runtime: body.rt-fx-off, window.__rtGrafana.fxOff and localStorage "rt-fx".
(() => {
  const button = htmlNode.getElementById('rt-fx');
  const root = htmlNode.querySelector('.rt-panel');
  const sync = () => {
    const off = document.body.classList.contains('rt-fx-off');
    if (button) { button.setAttribute('aria-pressed', String(!off)); button.textContent = 'CRT FX ' + (off ? 'OFF' : 'ON'); }
    if (root) root.dataset.fx = off ? 'off' : 'on';
  };
  if (button && !button.dataset.bound) {
    button.dataset.bound = '1';
    button.addEventListener('click', () => {
      const off = !document.body.classList.contains('rt-fx-off');
      document.body.classList.toggle('rt-fx-off', off);
      if (window.__rtGrafana) window.__rtGrafana.fxOff = off;
      try { localStorage.setItem('rt-fx', off ? 'off' : 'on'); } catch (e) { /* storage blocked: this page only */ }
      sync();
    });
  }
  sync();
})();

options.css:
/* Shared base for every retro HTML Graphics panel. Each panel renders in its own shadow DOM, so apply_theme.py
   copies this into each panel's CSS. Tokens match tokens/tokens.json and web/retro.css. */
* { box-sizing: border-box; }
.rt-panel {
  --rt-black: #050409;
  --rt-text: #f6f3ff;
  --rt-muted: #aba4cd;
  --rt-line: rgba(166, 61, 255, 0.3);
  --rt-c1: #4d5bff; --rt-c2: #a63dff; --rt-c3: #ff2e9a; --rt-c4: #ff3b3b;
  --rt-c5: #ff8c1a; --rt-c6: #ffd60a; --rt-c7: #9dff2e;
  --rt-cyan: #2de2ff; --rt-yellow: #ffef5c; --rt-red: #ff4d5e; --rt-green: #5dff8f; --rt-orange: #ff8c1a;
  --rt-stripes: linear-gradient(90deg, var(--rt-c1) 0 14.29%, var(--rt-c2) 0 28.57%, var(--rt-c3) 0 42.86%,
    var(--rt-c4) 0 57.14%, var(--rt-c5) 0 71.43%, var(--rt-c6) 0 85.71%, var(--rt-c7) 0);
  --rt-trail: linear-gradient(180deg, var(--rt-c2) 0 3px, transparent 3px 5px, var(--rt-c3) 5px 8px,
    transparent 8px 10px, var(--rt-c6) 10px 13px);
  --rt-glow-yellow: 0 0 2px rgba(255, 250, 210, 0.9), 0 0 10px rgba(255, 225, 60, 0.75), 0 0 26px rgba(255, 170, 20, 0.4);
  --rt-glow-cyan: 0 0 2px rgba(220, 250, 255, 0.9), 0 0 8px rgba(45, 226, 255, 0.65), 0 0 20px rgba(45, 140, 255, 0.4);
  --rt-glow-green: 0 0 2px rgba(220, 255, 230, 0.9), 0 0 8px rgba(93, 255, 143, 0.6), 0 0 18px rgba(40, 200, 90, 0.35);
  --rt-glow-red: 0 0 2px rgba(255, 220, 220, 0.9), 0 0 9px rgba(255, 77, 94, 0.75), 0 0 22px rgba(255, 40, 40, 0.4);
  --rt-split: -1.5px 0 rgba(255, 46, 154, 0.65), 1.5px 0 rgba(45, 226, 255, 0.65);
  --rt-font-display: "Exo 2", "Segoe UI", sans-serif;
  --rt-font-body: "Space Grotesk", "Segoe UI", system-ui, sans-serif;
  --rt-font-pixel: "Press Start 2P", ui-monospace, monospace;
  --rt-font-term: "VT323", ui-monospace, monospace;
  width: 100%;
  height: 100%;
  color: var(--rt-text);
  font-family: var(--rt-font-body);
  container-type: inline-size;
}

/* Dark panel with the 7-colour stripe cap, the card look of the kit. */
.rt-box {
  position: relative;
  border: 1px solid var(--rt-line);
  border-radius: 10px;
  background:
    repeating-linear-gradient(180deg, rgba(0, 0, 0, 0.16) 0 1px, transparent 1px 3px),
    linear-gradient(180deg, rgba(22, 17, 42, 0.92), rgba(10, 8, 20, 0.96));
  box-shadow: 0 18px 44px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.04);
}
.rt-box::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  border-radius: 9px 9px 0 0;
  background: var(--rt-stripes);
  opacity: 0.9;
}

.rt-label {
  color: var(--rt-cyan);
  font: 400 9px/1.4 var(--rt-font-pixel);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  text-shadow: 0 0 8px rgba(45, 226, 255, 0.5);
}

/* Speed stripes + drawn neon ring, the ident mark. */
.rt-mark { --rt-mark-size: 80px; display: flex; align-items: center; gap: calc(var(--rt-mark-size) * 0.14); flex: none; }
.rt-mark__stripes { display: flex; align-items: center; gap: calc(var(--rt-mark-size) * 0.05);
  height: calc(var(--rt-mark-size) * 0.9); transform: skewX(-22deg); }
.rt-mark__stripes i { --c: var(--rt-c1); display: block; width: calc(var(--rt-mark-size) * 0.085); height: 100%;
  border-radius: 999px; background: var(--c); box-shadow: 0 0 7px var(--c);
  animation: rt-trail-in 700ms cubic-bezier(0.16, 1, 0.3, 1) both; animation-delay: calc(var(--i, 0) * 45ms); }
.rt-mark__stripes i:nth-child(2) { --c: var(--rt-c2); --i: 1; }
.rt-mark__stripes i:nth-child(3) { --c: var(--rt-c3); --i: 2; }
.rt-mark__stripes i:nth-child(4) { --c: var(--rt-c4); --i: 3; }
.rt-mark__stripes i:nth-child(5) { --c: var(--rt-c5); --i: 4; }
.rt-mark__stripes i:nth-child(6) { --c: var(--rt-c6); --i: 5; }
.rt-mark__stripes i:nth-child(7) { --c: var(--rt-c7); --i: 6; }
.rt-mark__ring { position: relative; display: grid; place-items: center; width: var(--rt-mark-size);
  height: var(--rt-mark-size); flex: none; }
.rt-mark__ring svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; transform: rotate(-90deg); }
.rt-mark__ring circle { fill: none; stroke: var(--rt-yellow); stroke-width: 6; stroke-linecap: round;
  stroke-dasharray: 289; stroke-dashoffset: 289;
  filter: drop-shadow(0 0 3px #fff6a0) drop-shadow(0 0 9px rgba(255, 214, 10, 0.85));
  animation: rt-ring-draw 700ms cubic-bezier(0.65, 0, 0.35, 1) 300ms forwards; }
.rt-mark__ring img { width: 90%; height: 90%; object-fit: contain; opacity: 0; transform: scale(0.6);
  animation: rt-pop 450ms cubic-bezier(0.34, 1.56, 0.64, 1) 650ms forwards; }
/* No logo configured: the title's first letter in the ring, in pixel type. */
.rt-mark__glyph { color: var(--rt-cyan); font: 400 calc(var(--rt-mark-size) * 0.36)/1 var(--rt-font-pixel);
  text-shadow: var(--rt-glow-cyan); opacity: 0; animation: rt-pop 450ms cubic-bezier(0.34, 1.56, 0.64, 1) 650ms forwards; }

/* RGB-split glitch copies (screen readers read the heading once: empty alt text on the copies). */
.rt-glitch { position: relative; }
.rt-glitch::before, .rt-glitch::after {
  content: attr(data-text);
  content: attr(data-text) / "";
  position: absolute; inset: 0; pointer-events: none; opacity: 0;
  background: none; -webkit-text-stroke: 0; text-shadow: none; filter: none;
}
.rt-glitch::before { color: var(--rt-c3); -webkit-text-fill-color: var(--rt-c3); animation: rt-glitch-a 7s steps(1, end) infinite; }
.rt-glitch::after { color: var(--rt-cyan); -webkit-text-fill-color: var(--rt-cyan); animation: rt-glitch-b 7s steps(1, end) infinite; }
.rt-panel[data-fx="off"] .rt-glitch::before, .rt-panel[data-fx="off"] .rt-glitch::after { animation: none; }

@keyframes rt-blink { 50% { opacity: 0; } }
@keyframes rt-flicker-on { 0% { opacity: 0; } 8% { opacity: 1; } 12% { opacity: 0.15; } 20% { opacity: 1; }
  26% { opacity: 0.4; } 34%, 100% { opacity: 1; } }
@keyframes rt-trail-in { 0% { opacity: 0; transform: translateX(-40vw) scaleX(5); filter: blur(6px); }
  55% { opacity: 1; } 100% { opacity: 1; transform: none; filter: none; } }
@keyframes rt-trail-draw { from { transform: scaleX(0); } }
@keyframes rt-ring-draw { to { stroke-dashoffset: 0; } }
@keyframes rt-pop { to { opacity: 1; transform: none; } }
@keyframes rt-glitch-a {
  0%, 90.9% { opacity: 0; transform: none; clip-path: inset(0 0 0 0); }
  91% { opacity: 0.85; transform: translate(-4px, 0); clip-path: inset(12% 0 60% 0); }
  92.5% { opacity: 0.85; transform: translate(5px, 0); clip-path: inset(58% 0 18% 0); }
  94% { opacity: 0.85; transform: translate(-3px, 0); clip-path: inset(32% 0 44% 0); }
  95.5%, 100% { opacity: 0; transform: none; clip-path: inset(0 0 0 0); } }
@keyframes rt-glitch-b {
  0%, 91.4% { opacity: 0; transform: none; clip-path: inset(0 0 0 0); }
  91.5% { opacity: 0.85; transform: translate(4px, 0); clip-path: inset(64% 0 10% 0); }
  93% { opacity: 0.85; transform: translate(-5px, 0); clip-path: inset(8% 0 70% 0); }
  94.5% { opacity: 0.85; transform: translate(3px, 0); clip-path: inset(40% 0 38% 0); }
  96%, 100% { opacity: 0; transform: none; clip-path: inset(0 0 0 0); } }
@keyframes rt-alarm { 0%, 100% { box-shadow: 0 0 0 1px var(--rt-red), 0 0 22px rgba(255, 77, 94, 0.55); }
  50% { box-shadow: 0 0 0 1px rgba(255, 77, 94, 0.4), 0 0 6px rgba(255, 77, 94, 0.2); } }

@media (prefers-reduced-motion: reduce) {
  .rt-panel *, .rt-panel *::before, .rt-panel *::after {
    animation-duration: 0.01ms !important; animation-delay: 0s !important; animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important; }
}

.store { display: grid; grid-template-rows: auto 1fr; gap: 8px; padding: 2px; }
.store__head { display: flex; align-items: center; gap: 14px; padding: 0 4px; min-width: 0; }
.store__title {
  color: var(--rt-yellow);
  font: italic 800 15px/1.2 var(--rt-font-display);
  letter-spacing: 0.07em;
  text-transform: uppercase;
  text-shadow: -1px 0 rgba(255, 46, 154, 0.6), 1px 0 rgba(45, 226, 255, 0.6), 0 0 9px rgba(255, 214, 10, 0.55);
  white-space: nowrap;
}
.store__trail { flex: 1; height: 13px; background: var(--rt-trail); opacity: 0.6; transform-origin: left center;
  -webkit-mask-image: linear-gradient(90deg, #000, transparent); mask-image: linear-gradient(90deg, #000, transparent);
  animation: rt-trail-draw 900ms cubic-bezier(0.16, 1, 0.3, 1) both; }
.store__sub { color: var(--rt-muted); font: 400 17px/1 var(--rt-font-term); letter-spacing: 0.05em; text-transform: uppercase; white-space: nowrap; }
.store__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; min-height: 0; }
.cell { display: grid; align-content: space-between; gap: 6px; padding: 12px 14px 10px; min-width: 0; }
.cell__value { color: var(--rt-yellow); font: italic 900 30px/1 var(--rt-font-display);
  text-shadow: var(--rt-split), var(--rt-glow-yellow); white-space: nowrap; }
.cell__meta { color: var(--rt-green); font: 400 18px/1.1 var(--rt-font-term); letter-spacing: 0.05em; text-transform: uppercase;
  text-shadow: 0 0 6px rgba(93, 255, 143, 0.45); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
/* Power-cell bar: 20 slanted segments. */
.cell__bar { display: grid; grid-template-columns: repeat(20, minmax(0, 1fr)); gap: 3px; height: 16px; }
.cell__bar i { border-radius: 2px; transform: skewX(-18deg); background: rgba(255, 255, 255, 0.06); }
.cell__bar i.on { background: var(--rt-cyan); box-shadow: 0 0 6px rgba(45, 226, 255, 0.75); }
.cell__bar i.on:nth-child(n + 16) { background: var(--rt-c6); box-shadow: 0 0 6px rgba(255, 214, 10, 0.8); }
.cell__bar i.on:nth-child(n + 19) { background: var(--rt-red); box-shadow: 0 0 7px rgba(255, 77, 94, 0.85); }
.cell[data-state="warn"] .cell__value { color: var(--rt-orange); text-shadow: var(--rt-split), 0 0 10px rgba(255, 140, 26, 0.7); }
.cell[data-state="crit"] { animation: rt-alarm 1.2s ease-in-out infinite; }
.cell[data-state="crit"] .cell__value { color: #ff8b96; text-shadow: var(--rt-split), var(--rt-glow-red); }
@container (max-width: 900px) {
  .store__sub { display: none; }
  .cell__value { font-size: 24px; }
}
.cells__empty { color: var(--rt-muted); font: 400 20px/1.2 var(--rt-font-term); text-transform: uppercase; }

options.onRender:
// storage-cells: one power cell per filesystem. CFG: { usedRef: "A" (percent used per series),
// freeRef: "B" (bytes free per series, optional), label: "mountpoint" (series label to key on),
// order: ["/", "/data"] (optional; listed first, the rest follow sorted), names: { "/": "/ root" } (optional),
// warn: 75, crit: 90 }. Every series the query returns gets a cell, so new mounts show up on their own.
const CFG = {"title": "Filesystems", "subtitle": "used + free space", "usedRef": "A", "freeRef": "B", "label": "mountpoint", "order": ["/"]};
const host = htmlNode.getElementById('cells');
const lastNumber = (frame) => {
  const field = (frame.fields || []).find((f) => f.type === 'number');
  if (!field) return { value: null, labels: {} };
  const values = field.values && field.values.buffer ? field.values.buffer : field.values;
  const n = values ? values.length : 0;
  const raw = n ? (typeof values.get === 'function' ? values.get(n - 1) : values[n - 1]) : null;
  const v = raw === null || raw === undefined ? NaN : Number(raw); // a gap is "no data", never a real zero
  return { value: Number.isFinite(v) ? v : null, labels: field.labels || {} };
};
const bytes = (v) => {
  if (!Number.isFinite(v)) return '--';
  const units = ['B', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB'];
  let size = v;
  let i = 0;
  while (size >= 1024 && i < units.length - 1) { size /= 1024; i += 1; }
  return size.toFixed(size >= 100 ? 0 : size >= 10 ? 1 : 2) + ' ' + units[i] + ' free';
};
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const key = CFG.label || 'mountpoint';
const used = {};
const free = {};
const seen = {};
for (const frame of (data && data.series) || []) {
  const { value, labels } = lastNumber(frame);
  // Without the label: the legend name, else the n-th series of each query (so used and free still pair up).
  seen[frame.refId] = (seen[frame.refId] || 0) + 1;
  const id = labels[key] || frame.name || '#' + seen[frame.refId];
  if (frame.refId === (CFG.usedRef || 'A')) used[id] = value;
  else if (frame.refId === CFG.freeRef) free[id] = value;
}
const order = CFG.order || [];
const ids = Object.keys(used).sort((a, b) => {
  const ia = order.indexOf(a);
  const ib = order.indexOf(b);
  if (ia !== -1 || ib !== -1) return (ia === -1 ? 1e9 : ia) - (ib === -1 ? 1e9 : ib);
  return a.localeCompare(b);
});
const warnAt = Number.isFinite(CFG.warn) ? CFG.warn : 75;
const critAt = Number.isFinite(CFG.crit) ? CFG.crit : 90;
const html = ids.length ? ids.map((id) => {
  const u = used[id];
  const ok = Number.isFinite(u);
  const lit = ok ? Math.max(u > 0 ? 1 : 0, Math.min(20, Math.round(u / 5))) : 0;
  const state = !ok ? '' : u >= critAt ? 'crit' : u >= warnAt ? 'warn' : '';
  const segs = Array.from({ length: 20 }, (_, i) => (i < lit ? '<i class="on"></i>' : '<i></i>')).join('');
  return '<article class="rt-box cell"' + (state ? ' data-state="' + state + '"' : '') + '>' +
    '<div class="rt-label">' + esc((CFG.names && CFG.names[id]) || id) + '</div>' +
    '<div class="cell__value">' + (ok ? u.toFixed(1) + '%' : '--') + '</div>' +
    '<div class="cell__bar">' + segs + '</div>' +
    '<div class="cell__meta">' + (CFG.freeRef ? bytes(free[id]) : '&nbsp;') + '</div></article>';
}).join('') : '<div class="cells__empty">&gt; No filesystem data</div>';
if (host && host.__rtHtml !== html) { host.innerHTML = html; host.__rtHtml = html; }

